// View layer over the generated Platform API schema (plan-3).
//
// Rules:
//   - src/schema.gen.ts is generated by `make generate-contracts` and is
//     never hand-edited; this file is the package's public API.
//   - Every name below keeps the shape the console app compiled against in
//     phases 1–2 (the hand-transcribed types, validated against live API
//     payloads). Where the generated schema is equal or better, we derive
//     from it; where the spec is wrong or empty, the hand-validated shape
//     wins and the deviation is documented inline.
//   - App code imports only from this file, never from schema.gen.ts.

import type { components, operations } from './schema.gen.js';

type Schemas = components['schemas'];

// --- metadata -----------------------------------------------------------------
//
// The spec defines Cluster/NodePool metadata as an empty object
// (Record<string, never>), but live payloads carry full Kubernetes
// ObjectMeta (name, uid, labels, creationTimestamp, ...). Keep the
// hand-validated shape.
export interface ResourceMetadata {
  name: string;
  namespace?: string;
  uid?: string;
  resourceVersion?: string;
  generation?: number;
  creationTimestamp?: string;
  labels?: Record<string, string>;
  annotations?: Record<string, string>;
  finalizers?: string[];
  [key: string]: unknown;
}

// --- conditions and phases (derived) --------------------------------------------

export type ConditionStatus = NonNullable<Schemas['ClusterStatus']['conditions']>[number]['status'];

export type Condition = NonNullable<Schemas['ClusterStatus']['conditions']>[number];

export type ClusterPhase = NonNullable<Schemas['ClusterStatus']['phase']>;

export type NodePoolPhase = NonNullable<Schemas['NodePool']['status']>['phase'] extends
  infer P | undefined ? NonNullable<P> : never;

// --- status views (derived, with passthrough) ------------------------------------
//
// The intersection with { [key: string]: unknown } preserves the phase 1/2
// passthrough: the console can read fields the (weekly-updated) spec has not
// modeled yet without a contracts release.

export type ClusterStatus = Schemas['ClusterStatus'] & { [key: string]: unknown };

export type NodePoolStatus = NonNullable<Schemas['NodePool']['status']> & { [key: string]: unknown };

// --- resources --------------------------------------------------------------------
//
// Generated shapes with the metadata override above. The generated spec
// marks some observed-optional fields as required (e.g.
// hostedCluster.platform.aws.endpointAccess is absent from live payloads);
// the console only reads fields with optional chaining and never constructs
// these types, so requiredness does not affect it.

export type ClusterResource = Omit<Schemas['Cluster'], 'metadata' | 'status'> & {
  metadata: ResourceMetadata;
  status?: ClusterStatus;
};

export type NodePoolResource = Omit<Schemas['NodePool'], 'metadata' | 'status'> & {
  metadata: ResourceMetadata;
  status?: NodePoolStatus;
};

// Curated display subset of the cluster spec (phase 2 detail view). Kept
// hand-written and deliberately optional: it models what the console renders
// and what live payloads actually carry, not the full create-time contract.
export interface ClusterSpec {
  dnsReservationId?: string;
  oidcConfigId?: string;
  deleteProtection?: boolean;
  tags?: Record<string, string>;
  hostedCluster?: {
    release?: { image?: string };
    platform?: {
      type?: string;
      aws?: {
        region?: string;
        multiArch?: boolean;
        endpointAccess?: string;
        cloudProviderConfig?: {
          vpc?: string;
          zone?: string;
          subnet?: { id?: string };
        };
        rolesRef?: Record<string, string>;
      };
    };
    networking?: {
      machineNetwork?: Array<{ cidr?: string }>;
      clusterNetwork?: Array<{ cidr?: string; hostPrefix?: number }>;
      serviceNetwork?: Array<{ cidr?: string }>;
    };
    issuerURL?: string;
    fips?: boolean;
  };
  [key: string]: unknown;
}

export interface NodePoolSpec {
  nodePool?: {
    replicas?: number;
    [key: string]: unknown;
  };
  [key: string]: unknown;
}

// --- route response views (spec-derived; plan-3 T3.6) -------------------------------
//
// Typed from the generated path operations (listUserClusters,
// getUserCluster, listUserNodePools), remapped through the metadata
// override above because the spec types resource metadata as empty while
// live payloads carry full ObjectMeta.

type JsonBody<R> = R extends { content: { 'application/json': infer B } } ? B : never;
type OkBody<Op> = Op extends { responses: { 200: infer R } } ? JsonBody<R> : never;

type ClusterListRaw = OkBody<operations['listUserClusters']>;
type ClusterDetailRaw = OkBody<operations['getUserCluster']>;
type NodePoolListRaw = OkBody<operations['listUserNodePools']>;

export type ClusterList = Omit<ClusterListRaw, 'items'> & { items: ClusterResource[] };

export type ClusterDetail = Omit<ClusterDetailRaw, 'metadata' | 'status'> & {
  metadata: ResourceMetadata;
  status?: ClusterStatus;
};

export type NodePoolList = Omit<NodePoolListRaw, 'items'> & { items: NodePoolResource[] };

// DELETE /clusters/{id} — 202 Accepted; deletion is initiated, async.
export type ClusterDeletionAccepted = OkBody<operations['deleteUserCluster']>;

// DELETE /oidc_configs/{id} — 202 Accepted; deletion is initiated, async.
export type OidcConfigDeletionAccepted = OkBody<operations['deleteOidcConfig']>;

type OidcConfigRaw = OkBody<operations['getOidcConfig']>;

export type OidcConfigResource = Omit<OidcConfigRaw, 'metadata'> & {
  metadata: ResourceMetadata;
};

export type OidcConfigDetail = OidcConfigResource;

type OidcConfigListRaw = OkBody<operations['listOidcConfigs']>;

export type OidcConfigList = Omit<OidcConfigListRaw, 'items'> & {
  items: OidcConfigResource[];
};

// --- list envelopes -----------------------------------------------------------------
//
// Kept generic rather than deriving from ClusterList/NodePoolList: the BFF
// types its three routes against ResourceList<T> with the view-layer
// resource types, and the generated lists inline the raw (metadata-empty)
// schema shapes.

export interface ResourceList<T> {
  apiVersion?: string;
  kind?: string;
  metadata?: {
    continue?: string;
    remainingItemCount?: number;
    resourceVersion?: string;
    [key: string]: unknown;
  };
  items: T[];
}

// --- errors ---------------------------------------------------------------------------

// Matches the spec's Error schema (metav1.Status); the platform-specific
// code is prefixed to message (for example, "CLUSTERS-MGMT-GET-001: ...").
export type PlatformError = Schemas['Error'];

// --- console concepts (not part of the Platform API) -----------------------------------

export interface ConsoleUser {
  subject: string;
  name?: string;
  email?: string;
}
